import React, { useState, useEffect } from "react";
import "./McqGame.css";

const McqGame = ({
  question,
  onAnswerSubmit,
  timer,
  answerSubmitted,
  showFeedback,
  isCorrectAnswer,
}) => {
  const [selectedOption, setSelectedOption] = useState("");

  useEffect(() => {
    if (!answerSubmitted) {
      setSelectedOption("");
    }
  }, [question, answerSubmitted]);

  const getOptionClassName = (option) => {
    if (!answerSubmitted) {
      return `option-btn ${selectedOption === option ? "selected" : ""}`;
    }

    if (option === question.correct) {
      return "option-btn correct-answer";
    } else if (option === selectedOption && !isCorrectAnswer) {
      return "option-btn wrong-answer";
    } else {
      return "option-btn";
    }
  };

  return (
    <div className="mcq-question">
      <h2>{question.question}</h2>
      <div className="options-container">
        {question.options.map((option, index) => (
          <button
            key={index}
            className={getOptionClassName(option)}
            onClick={() => !answerSubmitted && setSelectedOption(option)}
            disabled={answerSubmitted}
          >
            {option}
          </button>
        ))}
      </div>

      {!answerSubmitted && (
        <button
          className="submit-btn"
          onClick={() => onAnswerSubmit(selectedOption)}
          disabled={!selectedOption}
        >
          Submit Answer
        </button>
      )}
    </div>
  );
};

export default McqGame;
